"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72846"],{39610(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_tamanho","status":422,"titulo":"Vers\xe3o do calend\xe1rio excede o tamanho permitido"},"descricao":{"codigo":"uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_tamanho","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["A vers\xe3o do calend\xe1rio de dias \xfateis vigente tem mais de 60 caracteres, contados depois de\\nretirar os espa\xe7os das pontas. \xc9 o mesmo limite do cadastro e da coluna que guarda a vers\xe3o: a\\nc\xf3pia n\xe3o aceita o que o cadastro de origem n\xe3o gravaria, porque um calend\xe1rio assim n\xe3o poderia\\nser relido depois.","O calend\xe1rio de dias \xfateis vigente \xe9 cadastrado no m\xf3dulo Configura\xe7\xe3o, e a vers\xe3o do processo\\ncongela uma c\xf3pia dele por valor, com a lista dos dias n\xe3o \xfateis (UNI-REQ-0080). Ao copi\xe1-lo, o\\nsistema confere de novo cada dia e o conjunto, e recusa o que o cadastro n\xe3o aceitaria. A recusa\\ns\xf3 vale para o processo que depende do calend\xe1rio, isto \xe9, o que tem prazo de recurso (ver\\n[calend\xe1rio vigente ausente](/erros/uniplus.selecao.processo_seletivo.calendario_vigente_ausente)); um processo sem contagem sobre dia \xfatil segue normalmente, porque n\xe3o usa o dado.","A confer\xeancia vem depois das da localidade ([`localidade_ausente`](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)) e da conven\xe7\xe3o de contagem\\n([`algoritmo_contagem_prazo_nao_declarado`](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado)), e antes das demais confer\xeancias de conformidade e do cronograma. A consulta de\\nconformidade do processo mostra o item \\"Calend\xe1rio de dias \xfateis vigente\\" como pendente enquanto o\\ncalend\xe1rio vigente estiver nessa condi\xe7\xe3o. Nada \xe9 gravado.","Os dias s\xe3o conferidos um a um, na ordem em que o calend\xe1rio os lista, e o primeiro dia com\\ndefeito interrompe a c\xf3pia. As confer\xeancias do calend\xe1rio como um todo (identificador, vers\xe3o,\\nlista vazia e dia repetido) v\xeam depois das de todos os dias. Esta confer\xeancia vem depois da vers\xe3o em branco\\n([`versao_do_calendario_obrigatoria`](/erros/uniplus.selecao.calendario_dias_uteis_congelado.versao_do_calendario_obrigatoria))."],"comoResolver":["A causa n\xe3o est\xe1 na configura\xe7\xe3o do processo, e nada nela corrige a recusa: o dado vem do\\ncalend\xe1rio de dias \xfateis vigente, cadastrado no m\xf3dulo Configura\xe7\xe3o. Como a vers\xe3o publicada\\ncongela o calend\xe1rio por valor, a corre\xe7\xe3o \xe9 na origem, antes de publicar ou retificar:\\ncadastre um calend\xe1rio corrigido, que o cadastro confere ao criar, coloque-o em vig\xeancia\\ne repita a opera\xe7\xe3o.","O cadastro recusa a vers\xe3o fora do limite ao criar o calend\xe1rio ([`versao_do_calendario_tamanho`](/erros/uniplus.configuracao.calendario_dias_uteis.versao_do_calendario_tamanho)). Um\\ncalend\xe1rio vigente nessa condi\xe7\xe3o indica dado gravado por caminho que n\xe3o passou por essa\\nconfer\xeancia, e a causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Calendario dias uteis congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);